def sortVowels(s):
    vowels = set('aeiouAEIOU')

    # Extract vowels from the string
    extracted_vowels = []
    for char in s:
        if char in vowels:
            extracted_vowels.append(char)

    # Sort vowels by ASCII value
    extracted_vowels.sort()

    # Reconstruct the string
    result = []
    vowel_index = 0

    for char in s:
        if char in vowels:
            # Place the next sorted vowel
            result.append(extracted_vowels[vowel_index])
            vowel_index += 1
        else:
            # Keep consonant in its original position
            result.append(char)

    return ''.join(result)
