def minimumDistance(points):
    def manhattan_distance(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def max_distance_without_point(points, skip_idx):
        max_dist = 0
        n = len(points)
        for i in range(n):
            if i == skip_idx:
                continue
            for j in range(i + 1, n):
                if j == skip_idx:
                    continue
                dist = manhattan_distance(points[i], points[j])
                max_dist = max(max_dist, dist)
        return max_dist

    n = len(points)
    min_max_distance = float('inf')

    # Try removing each point and find the minimum of maximum distances
    for i in range(n):
        max_dist = max_distance_without_point(points, i)
        min_max_distance = min(min_max_distance, max_dist)

    return min_max_distance
