def constructProductMatrix(grid):
    n = len(grid)
    m = len(grid[0])
    MOD = 12345

    # Calculate total product of all elements modulo MOD
    total_product = 1
    for i in range(n):
        for j in range(m):
            total_product = (total_product * grid[i][j]) % MOD

    # Create result matrix
    p = [[0] * m for _ in range(n)]

    # For each position, calculate product of all elements except the current one
    for i in range(n):
        for j in range(m):
            if grid[i][j] % MOD == 0:
                # If current element is divisible by MOD, we need to recalculate
                # the product without this element
                product_without_current = 1
                for row in range(n):
                    for col in range(m):
                        if row != i or col != j:
                            product_without_current = (product_without_current * grid[row][col]) % MOD
                p[i][j] = product_without_current
            else:
                # Use modular multiplicative inverse
                # (total_product / grid[i][j]) % MOD = (total_product * mod_inverse(grid[i][j], MOD)) % MOD
                current_val_mod = grid[i][j] % MOD
                if current_val_mod == 0:
                    p[i][j] = 0
                else:
                    # Calculate modular inverse using Fermat's little theorem
                    # Since MOD is prime, inverse of a is a^(MOD-2) mod MOD
                    inv = pow(current_val_mod, MOD - 2, MOD)
                    p[i][j] = (total_product * inv) % MOD

    return p
```

