def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    events = []
    index = 1
    for i in range(n):
        t = int(data[index]); x = int(data[index+1]); index += 2
        events.append((t, x))

    # Count how many monsters of each type appear
    monster_count = defaultdict(int)
    for t, x in events:
