            monster_count[x] += 1

    # We need to know when each event happens
    potion_events = []  # List of indices where t=1
    for i, (t, x) in enumerate(events):
        if t == 1:
            potion_events.append(i)

    # Simulate to check if it's possible to survive
    # We can use a greedy strategy with binary search on K (max potions held)

    def can_survive_with_max_potions(max_k, return_actions=False):
        # Track inventory of potions
        inventory = defaultdict(int)
        potions_held = 0  # current number of potions held
        actions = []  # for output: whether we pick up each potion (only when t=1)

        potion_event_idx = 0  # pointer to next potion event in potion_events

        for i, (t, x) in enumerate(events):
            if t == 1:
                # He finds a potion of type x
                # Decide whether to pick it up
                if potions_held < max_k:
                    # Pick it up
                    inventory[x] += 1
                    potions_held += 1
                    if return_actions:
                        actions.append(1)
                else:
                    # Cannot pick up
                    if return_actions:
                        actions.append(0)
            else:  # t == 2, monster of type x
                if inventory[x] > 0:
                    inventory[x] -= 1
                    potions_held -= 1
                else:
                    if return_actions:
                        return False, []
                    else:
                        return False

        if return_actions:
            return True, actions
        else:
            return True

    # First, check if it's possible at all
    if not can_survive_with_max_potions(n):  # use n as upper bound
        print(-1)
        return

    # Binary search on K_min
    left, right = 0, n
    best_k = n
    best_actions = None

    while left <= right:
        mid = (left + right) // 2
        success, actions = can_survive_with_max_potions(mid, return_actions=True)
        if success:
            best_k = mid
            best_actions = actions
            right = mid - 1
        else:
            left = mid + 1

