def minChanges(s, k):
    def is_palindrome(segment):
        return segment == segment[::-1]

    def min_changes_for_semi_palindrome(sub):
        n = len(sub)
        min_changes = float('inf')
        for d in range(1, n):
            if n % d == 0:
                changes = 0
                for i in range(d):
                    group = [sub[j] for j in range(i, n, d)]
                    mid = len(group) // 2
                    changes += sum(1 for idx in range(mid) if group[idx] != group[len(group) - 1 - idx])
                min_changes = min(min_changes, changes)
        return min_changes if min_changes != float('inf') else len(sub)

    n = len(s)
    # Precompute the cost for every substring
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n + 1):
            cost[i][j-1] = min_changes_for_semi_palindrome(s[i:j])

    # dp[i][p]: minimum changes to partition s[0:i] into p parts
    INF = float('inf')
    dp = [[INF] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for p in range(1, min(k, i) + 1):
            for j in range(p - 1, i):
                if dp[j][p - 1] != INF:
                    dp[i][p] = min(dp[i][p], dp[j][p - 1] + cost[j][i - 1])

    return dp[n][k]

