            # Check how large a holeless square we can form starting at (i, j)
            # Start with n = 1 and increase until we hit a hole or boundary
            n = 1
            while True:
                # Check if the n×n square with top-left at (i, j) is valid
                # Bottom-right corner is (i + n - 1, j + n - 1)
                if i + n - 1 > H or j + n - 1 > W:
                    break

                # Check if any cell in this n×n square is holed
                is_holeless = True
                for k in range(n):
                    for l in range(n):
                        if (i + k, j + l) in holed:
                            is_holeless = False
                            break
                    if not is_holeless:
                        break

                if is_holeless:
                    count += 1
                    n += 1
                else:
                    break

