def minAnagramLength(s):
    n = len(s)

    # Try all possible lengths of t from 1 to n
    for length in range(1, n + 1):
        # Check if n is divisible by length
        if n % length == 0:
            # Get the first segment as the reference anagram
            t = s[:length]
            t_count = {}
            for char in t:
                t_count[char] = t_count.get(char, 0) + 1

            # Check if all segments are anagrams of t
            valid = True
            for i in range(0, n, length):
                segment = s[i:i + length]
                segment_count = {}
                for char in segment:
                    segment_count[char] = segment_count.get(char, 0) + 1

                # Compare character frequencies
                if segment_count != t_count:
                    valid = False
                    break

            if valid:
                return length

    return n
