def kthSmallestAmount(coins, k):
    def count_multiples(x):
        """Count how many amounts <= x can be made with the given coins"""
        count = 0
        n = len(coins)

        # Use inclusion-exclusion principle
        # Iterate through all possible subsets of coins
        for mask in range(1, 1 << n):
            lcm_val = 1
            bit_count = 0

            for i in range(n):
                if mask & (1 << i):
                    # Calculate LCM of selected coins in this subset
                    import math
                    lcm_val = lcm_val * coins[i] // math.gcd(lcm_val, coins[i])
                    bit_count += 1

                    # Early termination if LCM exceeds x
                    if lcm_val > x:
                        break

            if lcm_val <= x:
                # Apply inclusion-exclusion: add for odd number of elements, subtract for even
                if bit_count % 2 == 1:
                    count += x // lcm_val
                else:
                    count -= x // lcm_val

        return count

    # Binary search for the kth smallest amount
    left, right = 1, k * min(coins)

    while left < right:
        mid = (left + right) // 2
        if count_multiples(mid) < k:
            left = mid + 1
        else:
            right = mid

    return left
