def findPrimePairs(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num ** 0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    # Generate list of primes up to n
    primes = []
    for i in range(2, n + 1):
        if is_prime(i):
            primes.append(i)

    # Create a set for O(1) lookup
    prime_set = set(primes)

    # Find prime pairs
    result = []
    for x in primes:
        y = n - x
        # Check if y is prime and x <= y
        if y in prime_set and x <= y:
            result.append([x, y])

    return result
