import sys

def main():
    input = sys.stdin.read
    data = input().splitlines()

    # Read N and Q
    N, Q = map(int, data[0].split())

    # Read the N x N pattern
    P = []
    for i in range(1, 1 + N):
        P.append(data[i].strip())

    # Precompute the number of black cells in one N x N block
    total_black = 0
    for i in range(N):
        for j in range(N):
            if P[i][j] == 'B':
                total_black += 1

    # Precompute prefix sums for rows and full grid
    # prefix[i][j] = number of black cells in P[0:i, 0:j]
    prefix = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            prefix[i][j] = prefix[i-1][j] + prefix[i][j-1] - prefix[i-1][j-1] + (1 if P[i-1][j-1] == 'B' else 0)

    def count_black_in_block(r1, c1, r2, c2):
        """Count black cells in the block from (r1, c1) to (r2, c2) inclusive"""
        if r1 > r2 or c1 > c2:
            return 0
        # Normalize to within [0, N)
        cnt = 0
        for i in range(r1, r2 + 1):
            for j in range(c1, c2 + 1):
                if P[i % N][j % N] == 'B':
                    cnt += 1
        return cnt

    def count_black_in_rectangle(a, b, c, d):
        """Count black cells in rectangle (a,b) to (c,d) inclusive"""
        # Break rectangle into parts:
        # Full blocks and partial edges

        # Total number of complete N x N blocks
        start_i, end_i = a, c
        start_j, end_j = b, d

        # Find the first and last full block indices
        first_full_i = (a + N - 1) // N * N if a % N != 0 else a
        first_full_j = (b + N - 1) // N * N if b % N != 0 else b
        last_full_i = (c + 1) // N * N - 1 if (c + 1) % N != 0 else c
        last_full_j = (d + 1) // N * N - 1 if (d + 1) % N != 0 else d

        total = 0

        # If valid, add full blocks
        if first_full_i <= last_full_i and first_full_j <= last_full_j:
            blocks_i = (last_full_i - first_full_i) // N + 1
            blocks_j = (last_full_j - first_full_j) // N + 1
            total += blocks_i * blocks_j * total_black
        else:
            first_full_i = last_full_i + 1  # No full blocks in i
            first_full_j = last_full_j + 1  # No full blocks in j

        # Add top strip: from (a, b) to (min(c, first_full_i - 1), d)
        if a <= last_full_i - 1:
            end_row = min(c, first_full_i - 1)
            total += count_black_in_block(a, b, end_row, d)

        # Add bottom strip: from (max(last_full_i + 1, a), b) to (c, d)
        if last_full_i + 1 <= c:
            start_row = max(last_full_i + 1, a)
            if start_row <= c:
                total += count_black_in_block(start_row, b, c, d)

        # Add left strip: from (first_full_i, b) to (last_full_i, min(d, first_full_j - 1))
        if first_full_i <= last_full_i and b <= first_full_j - 1:
            end_col = min(d, first_full_j - 1)
            total += count_black_in_block(first_full_i, b, last_full_i, end_col)

        # Add right strip: from (first_full_i, max(first_full_j, last_full_j + 1)) to (last_full_i, d)
        if first_full_i <= last_full_i and last_full_j + 1 <= d:
            start_col = max(first_full_j, last_full_j + 1)
            if start_col <= d:
                total += count_black_in_block(first_full_i, start_col, last_full_i, d)

        # However, the above overcounts the corners and misses the structure.
        # Let's switch to a cleaner modular arithmetic method.

        # Instead, use divide and conquer by full blocks
        total = 0

        # Function to count black in [r1, r2] x [c1, c2] within one block
        def count_in_single_block(r1, r2, c1, c2):
            cnt = 0
            for i in range(r1, r2 + 1):
                for j in range(c1, c2 + 1):
                    if P[i][j] == 'B':
                        cnt += 1
            return cnt

        # Count full N x N blocks
        full_blocks_i = (c + 1 - a) // N
        full_blocks_j = (d + 1 - b) // N

        # But better to align by mod
        start_i_mod = a % N
        start_j_mod = b % N
        end_i_mod = c % N
        end_i_block = c // N
        start_i_block = a // N
        end_j_mod = d % N
        start_j_block = b // N
        end_j_block = d // N

        # Case: within same block
        if start_i_block == end_i_block and start_j_block == end_j_block:
            return count_in_single_block(start_i_mod, end_i_mod, start_j_mod, end_j_mod)

        # Standard method: break into 4 parts: TL, TR, BL, BR and center
        # We can compute using inclusion
        def count_up_to(i, j):
            # Count black cells in [0, i] x [0, j]
            if i < 0 or j < 0:
                return 0
            full_blocks_i = i // N
            full_blocks_j = j // N
            rem_i = i % N
            rem_j = j % N
            cnt = full_blocks_i * full_blocks_j * total_black
            # Add right strip
            if rem_j >= 0:
                for r in range(0, rem_i + 1):
                    for c in range(0, N):
                        if P[r][c] == 'B':
                            cnt += full_blocks_j
                # Add bottom strip
                for r in range(0, N):
                    for c in range(0, rem_j + 1):
                        if P[r][c] == 'B':
                            cnt += full_blocks_i
                # Add corner
                cnt += prefix[rem_i + 1][rem_j + 1]
            else:
                # rem_i >= 0
                for r in range(0, rem_i + 1):
                    for c in range(0, N):
                        if P[r][c] == 'B':
                            cnt += full_blocks_j
            return cnt

        # But wait, better standard method:
        # Count from (0,0) to (c,d) minus the parts
        # Answer is f(c,d) - f(a-1,d) - f(c,b-1) + f(a-1,b-1)
        def f(r, c):
            if r < 0 or c < 0:
                return 0
            full_rows = r // N
            full_cols = c // N
            rem_row = r % N
            rem_col = c % N
            cnt = full_rows * full_cols * total_black
            # Add right partial strip (full rows, partial columns)
            for i in range(N):
                for j in range(rem_col + 1):
                    if P[i][j] == 'B':
                        cnt += full_rows
            # Add bottom partial strip (partial rows, full columns)
            for i in range(rem_row + 1):
                for j in range(N):
                    if P[i][j] == 'B':
                        cnt += full_cols
            # Add bottom-right corner
            for i in range(rem_row + 1):
                for j in range(rem_col + 1):
                    if P[i][j] == 'B':
                        cnt += 1
            return cnt

        result = f(c, d) - f(a-1, d) - f(c, b-1) + f(a-1, b-1)
        return result

    # Process queries
    out_lines = []
    for i in range(1 + N, 1 + N + Q):
        A, B, C, D = map(int, data[i].split())
        res = count_black_in_rectangle(A, B, C, D)
        out_lines.append(str(res))

    print('\n'.join(out_lines))

main()
