def solve(k, x):
    def price_sum_up_to(num):
        total_price = 0
        bit_pos = x
        while (1 << (bit_pos - 1)) <= num:
            block_size = 1 << bit_pos
            full_blocks = num // block_size
            count = full_blocks * (1 << (bit_pos - 1))
            remainder = num % block_size
            if remainder >= (1 << (bit_pos - 1)):
                count += remainder - (1 << (bit_pos - 1)) + 1
            total_price += count
            bit_pos += x
        return total_price

    left, right = 0, k * x
    while left < right:
        mid = (left + right + 1) // 2
        if price_sum_up_to(mid) <= k:
            left = mid
        else:
            right = mid - 1
    return left

