from collections import defaultdict

def canTraverseAllPairs(nums):
    n = len(nums)

    # Edge case: single element is trivially connected
    if n == 1:
        return True

    # Step 1: For each number, find its prime factors and map prime -> indices
    prime_to_indices = defaultdict(set)

    for i, num in enumerate(nums):
        temp = num
        p = 2
        while p * p <= temp:
            if temp % p == 0:
                prime_to_indices[p].add(i)
                while temp % p == 0:
                    temp //= p
            p += 1
        if temp > 1:
            prime_to_indices[temp].add(i)

    # Step 2: Use union-find (disjoint set) to connect indices via shared prime factors
    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[rx] = ry

    # For each prime, union all indices that share this prime
    for indices in prime_to_indices.values():
        idx_list = list(indices)
        for j in range(1, len(idx_list)):
            union(idx_list[j], idx_list[0])

    # Step 3: Check if all indices are in the same connected component
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False

    return True

